from ansible.vars.hostvars import HostVars

class UnsafeValue(object):
    __UNSAFE__ = True

class DummyTemplar(object):
    def __init__(self):
        self.calls = []
        self.undefined_value = object()
        self.error_value = object()
        self.available_variables = {
            'shared': 'available',
            'normal': 'raw',
            'vars': {'answer': 42},
            'hostvars': object.__new__(HostVars),
            'unsafe': UnsafeValue(),
            'undefined': self.undefined_value,
            'error': self.error_value,
        }

    def template(self, value):
        self.calls.append(value)
        if value is self.undefined_value:
            raise AnsibleUndefinedVariable('inner failure')
        if value is self.error_value:
            raise ValueError('boom')
        return 'templated:%s' % value

templar = DummyTemplar()
local_value = object()
global_value = object()
variables = AnsibleJ2Vars(
    templar,
    {
        'shared': 'global',
        'global_only': global_value,
        'context': 'global context',
    },
    {
        'shared': local_value,
        'l_scoped': 'scoped value',
        'context': 'ignored local context',
        'missing_local': missing,
    },
)

assert variables['shared'] is local_value
assert variables['scoped'] == 'scoped value'
assert variables['context'] == 'global context'
assert variables['global_only'] is global_value
assert templar.calls == []

assert variables['normal'] == 'templated:raw'
assert templar.calls == ['raw']

templar.calls[:] = []
assert variables['vars'] is templar.available_variables['vars']
assert variables['hostvars'] is templar.available_variables['hostvars']
assert variables['unsafe'] is templar.available_variables['unsafe']
assert templar.calls == []

try:
    variables['does_not_exist']
except KeyError as exc:
    assert 'undefined variable: does_not_exist' in str(exc)
else:
    assert False, 'Expected KeyError for an unknown variable'

try:
    variables['undefined']
except AnsibleUndefinedVariable as exc:
    assert 'inner failure' in to_native(exc)
else:
    assert False, 'Expected AnsibleUndefinedVariable'

try:
    variables['error']
except AnsibleError as exc:
    message = to_native(exc)
    assert 'unhandled exception' in message
    assert 'boom' in message
else:
    assert False, 'Expected AnsibleError'

